








WITH plan AS (
    VALUES (9201, 1, 'UI Smoke Plan', 9202, false)
    ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, current_revision_id = EXCLUDED.current_revision_id, archived = EXCLUDED.archived
    RETURNING id
)
SELECT 9202, id, 1, 40, 2026, 85, 60, 90000, 12000, 36000, 6000, 0.025, 0.02, 0.025, 'SIMPLE_WATERFALL', 2, 0.05, 0.25, true, 0.04, 0.07, 67, 24000, 0.19, 'CASH,BONDS,STOCKS', 2026, 15000, 0, 341700, 21600, 1000, 1, 'SOURCE', 'SOURCE'
FROM plan
ON CONFLICT (id) DO NOTHING;

UPDATE investory.simulation_plans SET current_revision_id = 9202 WHERE id = 9201;


